#!/usr/bin/env python3
"""Writes the texts the tests of Specs/text_rules.t27 use, from the readable list below.

The spec carries one generated block between
    ; >>> generated by Specs/tables/text_tables.py ...
    ; <<< generated
with named row indexes and the texts as packed UTF-8 bytes with offsets and lengths (t27 has no string
arrays that reach C). Run by Specs/generate.sh; edit the list here, not the spec. The table layout is
ponte_tables.table, so every spec's fixtures read the same way.
"""
import pathlib
import re
import sys

sys.dont_write_bytecode = True
from ponte_tables import table  # noqa: E402  (same folder; generate.sh runs this file directly)

SPECS = pathlib.Path(__file__).resolve().parents[1]
BEGIN = "; >>> generated by Specs/tables/text_tables.py -- edit the list there, not here"

# Russian (and a little English) as the owner types it. *_1, *_2, *_3: the phrases the text splits into.
DOBRYI = "Добрый день, коллеги."
ZOVUT = "Меня зовут Дмитрий."
TRINITY = "Я представляю компанию Trinity."
INITIAL_1 = ("Встреча с Д. Фёдоровым "
             "назначена на завтра.")
QUOTE_1 = "Он сказал: «Да, конечно.»"
BANG_1 = "Сколько стоит доставка?!"
ELLIPSIS_1 = "Минуточку, подождите…"
DECIMAL_1 = "Курс сейчас 5.4 реала за доллар."
PARAGRAPH_1 = "Первый абзац без точки в конце"
SMILES_1 = ("Спасибо всем за встречу, "
            "до завтра!")
LIST_LONG_1 = ("Пункты для обсуждения, "
               "без точек в конце")

TEXT_FIXTURES = [
    ("THREE", DOBRYI + " " + ZOVUT + " " + TRINITY),
    ("THREE_1", DOBRYI),
    ("THREE_2", ZOVUT),
    ("THREE_3", TRINITY),
    # "Privet! Kak dela? Da.": short sentences and a short tail stay one phrase.
    ("SHORT", "Привет! Как дела? Да."),
    ("LATIN", "Hi. OK? Good morning, everyone, nice to meet you all. Bye."),
    # "... i t. d. Potom ...": dots after one-letter words.
    ("ABBREV", "Мы обсудили цены, сроки "
               "и т. д. Потом поговорим "
               "о доставке."),
    ("INITIAL", INITIAL_1 + " Он подтвердит время."),
    ("INITIAL_1", INITIAL_1),
    ("QUOTE", QUOTE_1 + " Потом мы подписали "
                        "договор."),
    ("QUOTE_1", QUOTE_1),
    ("BANG", BANG_1 + " Нам нужно знать это "
                      "заранее."),
    ("BANG_1", BANG_1),
    ("ELLIPSIS", ELLIPSIS_1 + " Я проверю расписание "
                              "на завтра."),
    ("ELLIPSIS_1", ELLIPSIS_1),
    ("DECIMAL", DECIMAL_1 + " Это нормально для нас."),
    ("DECIMAL_1", DECIMAL_1),
    ("PARAGRAPH", PARAGRAPH_1 + "\n\nВторой абзац тоже "
                                "без точки"),
    ("PARAGRAPH_1", PARAGRAPH_1),
    ("LINES", "Цена: шестьсот евро\n"
              "Доставка: тридцать евро"),
    ("SMILES", SMILES_1 + " :) :) :) :) :) :) :) :) :)"),
    ("SMILES_1", SMILES_1),
    # Longer than a phrase without a sentence end: a line feed, commas only, spaces only, one long word.
    ("LIST_LONG", LIST_LONG_1 + "\n" + "цены, сроки, "
                  "доставка, оплата, " * 10
                  + "гарантия"),
    ("LIST_LONG_1", LIST_LONG_1),
    ("COMMAS_LONG", "Нам нужны "
                    + "яблоки, груши, сливы, " * 12
                    + "и вишни"),
    ("WORDS_LONG", "слово " * 70 + "конец"),
    ("ZHE_LONG", "ж" * 250),
    ("SPACES", "   \n\t  "),
    ("EMPTY", ""),
]


def write_block(spec_name, lines):
    spec = SPECS / spec_name
    source = spec.read_text()
    block = "\n".join([BEGIN] + lines + ["; <<< generated"])
    source, n = re.subn(re.escape(BEGIN) + r".*?; <<< generated", lambda _: block, source, flags=re.S)
    if n != 1:
        sys.exit(f"{spec_name}: generated block not found")
    if any(ord(ch) > 127 for ch in source):
        sys.exit(f"{spec_name}: not ASCII after generation")
    if spec.read_text() != source:
        spec.write_text(source)


def main():
    write_block("text_rules.t27", table("TX_FX", "Texts for the tests", TEXT_FIXTURES, []))
    print(f"text tables: {len(TEXT_FIXTURES)} fixtures")


if __name__ == "__main__":
    main()
